import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int units = sc.nextInt();
        double bill = 0;
        if (units > 200) {
            bill += (units - 200) * 8.0;
            units = 200;
        }
        if (units > 100) {
            bill += (units - 100) * 5.0;
            units = 100;
        }
        bill += units * 3.5;
        System.out.printf("%.2f%n", bill);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int work = n;
        int count = 0;
        while (work != 0) {
            count += work & 1;
            work >>>= 1;
        }
        int probe = n;
        int pos = -1;
        while (probe != 0) {
            probe >>>= 1;
            pos++;
        }
        boolean pow2 = n > 0 && (n & (n - 1)) == 0;
        System.out.println("Set bits: " + count);
        System.out.println("Highest position: " + pos);
        System.out.println("Power of two: " + pow2);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double salary = sc.nextDouble();
        int years = sc.nextInt();
        int rating = sc.nextInt();
        int pct = (rating == 1) ? ((years >= 5) ? 20 : 15) : (rating == 2) ? ((years >= 5) ? 12 : 8) : 5;
        double bonus = salary * pct / 100.0;
        double total = salary + bonus;
        int monthly = (int) (bonus / 12);
        System.out.printf("Bonus: %.2f%n", bonus);
        System.out.printf("New salary: %.2f%n", total);
        System.out.println("Monthly hike: " + monthly);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String binary = "";
        long p = 1L << 30;
        while (p > 0 && (n & p) == 0) {
            p >>= 1;
        }
        if (n == 0) {
            binary = "0";
        }
        while (p > 0) {
            binary += ((n & p) != 0) ? "1" : "0";
            p >>= 1;
        }
        System.out.println("Binary: " + binary);
        System.out.println("Doubled: " + (n << 1));
        System.out.println("Halved: " + (n >> 1));
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();
        long m = sc.nextLong();
        long result = 1 % m;
        long base = a % m;
        while(b > 0) {
            if ((b & 1) == 1) {
                result = result * base % m;
            }
            base = base * base % m;
            b >>= 1;
        }
        System.out.println(result);
    }
}
